// INFINORA 2026 — registration confirmation + personalized PDF.
// Trigger: Supabase Database Webhook on INSERT into public.registrations.
// Required secrets: BREVO_API_KEY, SENDER_EMAIL, SENDER_NAME, WEBHOOK_SECRET.
// SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are supplied by Supabase.

import { PDFDocument, StandardFonts, rgb } from "npm:pdf-lib@1.17.1";

const PARCHMENT_JPG_BASE64 = "";

const esc = (v: unknown) =>
  String(v ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]!));

const formatDate = (value: string | null | undefined) =>
  new Intl.DateTimeFormat("en-IN", {
    dateStyle: "medium",
    timeStyle: "short",
    timeZone: "Asia/Kolkata",
  }).format(value ? new Date(value) : new Date());

async function createRegistrationPdf(r: Record<string, unknown>) {
  const pdf = await PDFDocument.create();
  const regular = await pdf.embedFont(StandardFonts.Helvetica);
  const bold = await pdf.embedFont(StandardFonts.HelveticaBold);
  const jpgBytes = Uint8Array.from(atob(PARCHMENT_JPG_BASE64), (c) => c.charCodeAt(0));
  const parchment = await pdf.embedJpg(jpgBytes);
  const ink = rgb(0.22, 0.12, 0.035);
  const muted = rgb(0.34, 0.22, 0.08);
  const gold = rgb(0.43, 0.29, 0.11);
  const width = 595.28, height = 841.89;
  const addBackground = () => {
    const page = pdf.addPage([width, height]);
    page.drawImage(parchment, { x: 0, y: 0, width, height });
    return page;
  };
  const center = (page: any, text: string, y: number, size: number, font = regular) => {
    const w = font.widthOfTextAtSize(text, size);
    page.drawText(text, { x: (width - w) / 2, y, size, font, color: ink });
  };

  const eventName = String(r.event_name ?? "");
  const eventId = String(r.event_id ?? "");
  const teamMembers = Array.isArray(r.participants) && r.participants.length
    ? r.participants as Array<Record<string, unknown>>
    : [{ name: r.participant_name, fictional_name: r.fictional_name, character: r.game_character }];
  const preparedOn = formatDate(String(r.created_at ?? ""));

  // PAGE 1 - registration and contact details.
  const page1 = addBackground();
  center(page1, "YOUR JOURNEY AWAITS", 330, 19, bold);
  center(page1, "REGISTRATION RECEIVED", 307, 10, bold);
  page1.drawLine({ start: { x: 105, y: 296 }, end: { x: 490, y: 296 }, thickness: 0.8, color: gold });
  const rows: [string, string][] = [
    ["TEAM LEAD", String(r.participant_name ?? "")],
    ["COLLEGE", String(r.college ?? "")],
    ["DEPARTMENT", String(r.department ?? "")],
    ["YEAR", String(r.study_year ?? "")],
    ["SHIFT", String(r.shift ?? "")],
    ["EVENT", `EVENT ${eventId} - ${eventName}`],
    ["TEAM SIZE", String(teamMembers.length)],
    ["REFERENCE ID", String(r.reference_code ?? "")],
    ["PREPARED ON", preparedOn],
  ];
  let y = 276;
  for (const [label, value] of rows) {
    page1.drawText(label, { x: 105, y, size: 9.2, font: bold, color: muted });
    let valueSize = 9.2;
    while (bold.widthOfTextAtSize(value, valueSize) > 245 && valueSize > 7) valueSize -= 0.3;
    const valueWidth = bold.widthOfTextAtSize(value, valueSize);
    page1.drawText(value, { x: 490 - valueWidth, y, size: valueSize, font: bold, color: ink });
    page1.drawLine({ start: { x: 105, y: y - 5 }, end: { x: 490, y: y - 5 }, thickness: 0.35, color: gold, opacity: 0.55 });
    y -= 24;
  }
  center(page1, "TEAM PARTICIPANTS ARE LISTED ON PAGE 2", y - 14, 8, bold);
  center(page1, "INFINORA 2026 ORGANISING COMMITTEE", y - 29, 8, regular);

  // PAGE 2 - one participant per row, with Math Bid character details where applicable.
  const page2 = addBackground();
  center(page2, "TEAM PARTICIPANTS", 735, 19, bold);
  center(page2, `EVENT ${eventId} - ${eventName}`, 710, 10, bold);
  center(page2, `REFERENCE ID: ${String(r.reference_code ?? "")}`, 691, 8, regular);
  page2.drawLine({ start: { x: 72, y: 672 }, end: { x: 523, y: 672 }, thickness: 0.8, color: gold });

  const isMathBid = eventId === "09";
  const xNo = 82, xName = 125, xFictional = 335, xCharacter = 455;
  page2.drawText("NO.", { x: xNo, y: 650, size: 8.5, font: bold, color: muted });
  page2.drawText("PARTICIPANT NAME", { x: xName, y: 650, size: 8.5, font: bold, color: muted });
  if (isMathBid) {
    page2.drawText("FICTIONAL NAME", { x: xFictional, y: 650, size: 8, font: bold, color: muted });
    page2.drawText("CHARACTER", { x: xCharacter, y: 650, size: 8, font: bold, color: muted });
  }
  page2.drawLine({ start: { x: 72, y: 640 }, end: { x: 523, y: 640 }, thickness: 0.6, color: gold });

  let participantY = 615;
  teamMembers.forEach((member, index) => {
    const name = String(member.name ?? "");
    page2.drawText(String(index + 1).padStart(2, "0"), { x: xNo, y: participantY, size: 9, font: regular, color: ink });
    let nameSize = 9;
    while (regular.widthOfTextAtSize(name, nameSize) > (isMathBid ? 195 : 375) && nameSize > 7) nameSize -= 0.3;
    page2.drawText(name, { x: xName, y: participantY, size: nameSize, font: regular, color: ink });
    if (isMathBid) {
      const fictional = String(member.fictional_name ?? "");
      const character = String(member.character ?? "");
      page2.drawText(fictional, { x: xFictional, y: participantY, size: 8.2, font: regular, color: ink });
      page2.drawText(character, { x: xCharacter, y: participantY, size: 8.2, font: regular, color: ink });
    }
    page2.drawLine({ start: { x: 72, y: participantY - 9 }, end: { x: 523, y: participantY - 9 }, thickness: 0.35, color: gold, opacity: 0.5 });
    participantY -= 31;
  });
  center(page2, "PLEASE KEEP BOTH PAGES FOR YOUR RECORDS", 105, 8, bold);
  center(page2, "INFINORA 2026 ORGANISING COMMITTEE", 88, 8, regular);
  return await pdf.save();
}

Deno.serve(async (req) => {
  if (req.headers.get("x-webhook-secret") !== Deno.env.get("WEBHOOK_SECRET")) {
    return new Response("Unauthorized", { status: 401 });
  }

  const payload = await req.json().catch(() => null);
  if (!payload || payload.type !== "INSERT" || !payload.record) {
    return new Response("Ignored", { status: 200 });
  }

  const r = payload.record;
  const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
  const svc = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

  // Find the WhatsApp group for this event.
  let candidate = "";
  try {
    const g = await fetch(
      `${supabaseUrl}/rest/v1/event_groups?event_id=eq.${encodeURIComponent(r.event_id)}&select=whatsapp_link`,
      { headers: { apikey: svc, Authorization: `Bearer ${svc}` } },
    );
    if (g.ok) candidate = ((await g.json())[0]?.whatsapp_link ?? "").trim();
  } catch (e) {
    console.error("event_groups lookup failed", e);
  }
  const groupLink = /^https:\/\/chat\.whatsapp\.com\/[A-Za-z0-9]+/.test(candidate) ? candidate : "";

  // Create and upload a private PDF before sending the email.
  const safeReference = String(r.reference_code ?? `registration-${r.id}`).replace(/[^A-Za-z0-9_-]/g, "_");
  const pdfPath = `${String(r.event_id)}/${safeReference}.pdf`;
  let pdfDownloadUrl = "";
  try {
    const pdfBytes = await createRegistrationPdf(r);
    const upload = await fetch(`${supabaseUrl}/storage/v1/object/registration-pdfs/${pdfPath}`, {
      method: "POST",
      headers: {
        apikey: svc,
        Authorization: `Bearer ${svc}`,
        "Content-Type": "application/pdf",
        "x-upsert": "true",
      },
      body: pdfBytes,
    });
    if (!upload.ok) throw new Error(`PDF upload failed (${upload.status}): ${await upload.text()}`);

    const signed = await fetch(`${supabaseUrl}/storage/v1/object/sign/registration-pdfs/${pdfPath}`, {
      method: "POST",
      headers: {
        apikey: svc,
        Authorization: `Bearer ${svc}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ expiresIn: 2592000 }), // 30 days
    });
    if (!signed.ok) throw new Error(`PDF signed URL failed (${signed.status}): ${await signed.text()}`);
    const signedData = await signed.json();
    const signedPath = signedData.signedURL ?? signedData.signedUrl;
    pdfDownloadUrl = signedPath.startsWith("http") ? signedPath : `${supabaseUrl}/storage/v1${signedPath}`;

    const savedPath = await fetch(`${supabaseUrl}/rest/v1/registrations?id=eq.${encodeURIComponent(r.id)}`, {
      method: "PATCH",
      headers: {
        apikey: svc,
        Authorization: `Bearer ${svc}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ registration_pdf_path: pdfPath }),
    });
    if (!savedPath.ok) throw new Error(`Could not save PDF path: ${await savedPath.text()}`);
  } catch (e) {
    console.error("Registration PDF generation failed", e);
    return new Response("Registration PDF generation failed", { status: 502 });
  }

  const isMathBid = r.event_id === "09";
  const rows: [string, string][] = [
    ["Participant", r.participant_name],
    ["College", r.college],
    ["Department", r.department],
    ["Year", r.study_year],
    ["Shift", r.shift ?? ""],
    ["Event", `Event ${r.event_id} – ${r.event_name ?? ""}`],
  ];
  const teamMembers = Array.isArray(r.participants) ? r.participants : [];
  if (teamMembers.length) {
    rows.push(["Team members", teamMembers.map((p: any, i: number) => `${i + 1}. ${p.name}${isMathBid ? ` — ${p.fictional_name} (${p.character})` : ""}`).join("; ")]);
  } else if (isMathBid) {
    rows.push(["Fictional name", r.fictional_name], ["Character", r.game_character]);
  }
  rows.push(["Reference ID", r.reference_code], ["Prepared on", formatDate(r.created_at)]);

  const rowsHtml = rows.map(([k, v]) =>
    `<tr><td style="padding:7px 0;color:#7a5a2c;font-size:12px;letter-spacing:1px;text-transform:uppercase">${esc(k)}</td>` +
    `<td style="padding:7px 0;color:#2f1c08;font-weight:600;text-align:right">${esc(v)}</td></tr>`).join("");

  const groupHtml = groupLink
    ? `<p style="margin:26px 0 8px;text-align:center"><a href="${esc(groupLink)}" style="display:inline-block;background:#25a244;color:#ffffff;text-decoration:none;font-weight:700;padding:14px 26px;border-radius:4px">Join the WhatsApp group</a></p>
       <p style="margin:0;text-align:center;font-size:12px;color:#7a5a2c">Tap the button above on your phone. Please do not share this link outside your registration.</p>`
    : `<p style="text-align:center;color:#7a5a2c;font-size:13px">The WhatsApp group link will be shared with you soon.</p>`;

  const pdfHtml = `<p style="margin:18px 0 8px;text-align:center"><a href="${esc(pdfDownloadUrl)}" style="display:inline-block;background:#34213e;color:#f4e8c9;text-decoration:none;font-weight:700;padding:14px 26px;border:1px solid #b58a4b;border-radius:4px">Download Registration PDF</a></p>
    <p style="margin:0;text-align:center;font-size:12px;color:#7a5a2c">Your personalized registration receipt is available for download for 30 days.</p>`;

  const html = `<div style="margin:0;background:#100d1b;padding:28px 14px;font-family:Georgia,'Times New Roman',serif;color:#2d1c0c">
  <div style="max-width:600px;margin:0 auto;background:#f4e8c9;border:1px solid #b58a4b;box-shadow:0 0 0 6px #21172a,0 0 28px #b58a4b">
    <div style="padding:26px 30px 12px;text-align:center;background:linear-gradient(135deg,#21172a,#34213e);color:#e8cf91">
      <p style="margin:0;font-size:11px;letter-spacing:5px">✦ THE INFINORA ARCHIVES ✦</p>
      <h1 style="margin:14px 0 5px;font-size:29px;letter-spacing:3px;font-weight:normal">INFINORA 2026</h1>
      <p style="margin:0;font-size:12px;letter-spacing:2px;color:#d4bd8b">A CELEBRATION OF TALENT &amp; IMAGINATION</p>
    </div>
    <div style="padding:30px">
      <p style="margin:0 0 18px;font-size:17px">Dear <strong>${esc(r.participant_name)}</strong>,</p>
      <h2 style="margin:0 0 18px;text-align:center;font-size:25px;font-weight:normal;color:#4b2e58">Your place has been reserved!</h2>
      <p style="font-size:15px;line-height:1.8;margin:0 0 18px">Congratulations! We are delighted to welcome you as a participant of <strong>INFINORA 2026</strong>. Your registration has been successfully received by the organising team. Your journey into a world of creativity, challenges and extraordinary talent begins here.</p>
      <div style="border-top:1px solid #b58a4b;border-bottom:1px solid #b58a4b;padding:14px 0;margin:20px 0">
        <p style="margin:0 0 12px;text-align:center;font-size:11px;letter-spacing:3px;color:#79572f">YOUR REGISTRATION DETAILS</p>
        <table width="100%" style="border-collapse:collapse">${rowsHtml}</table>
      </div>
      ${groupHtml}
      ${pdfHtml}
      <p style="font-size:14px;line-height:1.8;margin:22px 0 0">Please keep this letter for your reference and join your event's WhatsApp group using the button above. Important event updates and instructions will be shared by the organisers.</p>
      <p style="font-size:15px;line-height:1.8;margin:22px 0 0">We look forward to welcoming you. Until then, prepare well and let your talent shine!</p>
      <p style="font-size:15px;line-height:1.7;margin:20px 0 0">With warm wishes,<br><strong>INFINORA 2026 Organising Committee</strong></p>
    </div>
    <div style="padding:14px 20px;text-align:center;background:#21172a;color:#d8c18f;font-size:11px;letter-spacing:1px">✦ THIS IS AN AUTOMATED CONFIRMATION LETTER ✦</div>
  </div></div>`;

  const res = await fetch("https://api.brevo.com/v3/smtp/email", {
    method: "POST",
    headers: { "api-key": Deno.env.get("BREVO_API_KEY")!, "content-type": "application/json" },
    body: JSON.stringify({
      sender: { name: Deno.env.get("SENDER_NAME") || "INFINORA", email: Deno.env.get("SENDER_EMAIL") },
      to: [{ email: r.email, name: r.participant_name }],
      subject: `Your INFINORA 2026 invitation is confirmed – ${r.event_name ?? `Event ${r.event_id}`}`,
      htmlContent: html,
    }),
  });

  if (!res.ok) {
    console.error("Brevo error", res.status, await res.text());
    return new Response("Email failed", { status: 502 });
  }

  await fetch(`${supabaseUrl}/rest/v1/registrations?id=eq.${encodeURIComponent(r.id)}`, {
    method: "PATCH",
    headers: { apikey: svc, Authorization: `Bearer ${svc}`, "content-type": "application/json" },
    body: JSON.stringify({ confirmation_sent_at: new Date().toISOString() }),
  });

  return new Response("Sent", { status: 200 });
});
